"""Ensemble (V2 + V3) for Fox vs NBC headlines: averaged TF-IDF + LR pipelines."""

import base64
import gzip
import pickle

import numpy as np


_WEIGHTS_B64 = """"""


def _load():
    raw = base64.b64decode(_WEIGHTS_B64.strip())
    return pickle.loads(gzip.decompress(raw))


_LABELS = {0: "NBC", 1: "FoxNews"}


class Model:
    def __init__(self):
        self.pipes = _load()

    def predict(self, batch):
        if hasattr(batch, "tolist"):
            batch = batch.tolist()
        if isinstance(batch, str):
            batch = [batch]
        else:
            batch = [str(x) for x in batch]
        probs = np.mean([p.predict_proba(batch) for p in self.pipes], axis=0)
        ids = probs.argmax(axis=1)
        return [_LABELS[int(i)] for i in ids]

    def __call__(self, batch):
        return self.predict(batch)


def get_model():
    return Model()
